<?php
declare(strict_types=1);
$root=dirname(__DIR__);
function voiceBrainCheck(bool $ok,string $name):void{if(!$ok)throw new RuntimeException('Voice Agent Brain integration: '.$name);}
$api=(string)file_get_contents($root.'/api/agent-workspace.php');
$kds=(string)file_get_contents($root.'/api/kds-agent.php');
$brain=(string)file_get_contents($root.'/includes/agent-voice-conversation.php');
$history=(string)file_get_contents($root.'/includes/agent-workspace-core.php');
$global=(string)file_get_contents($root.'/js/global-agent.js');
$voice=(string)file_get_contents($root.'/js/kds-voice-listener.js');
$sidebar=(string)file_get_contents($root.'/js/kds-agent-sidebar.js');
$canvas=(string)file_get_contents($root.'/js/dynamic-agent-canvas.js');
$page=(string)file_get_contents($root.'/kds.php');
voiceBrainCheck(str_contains($brain,"voice_identity_events"),'must reuse enrolled voice events');
voiceBrainCheck(str_contains($brain,"voice_identity_profiles")&&str_contains($brain,"p.status='active'"),'disabled voice profiles cannot personalize');
voiceBrainCheck(str_contains($brain,"e.session_user_id=?"),'verification belongs to current signed-in actor');
voiceBrainCheck(str_contains($brain,"voice.manage"),'cross-user greeting requires manage permission');
voiceBrainCheck(str_contains($brain,'DATE_SUB(NOW(6),INTERVAL 15 MINUTE)'),'expired matches never greet by name');
voiceBrainCheck(str_contains($brain,"role='user'")&&str_contains($brain,'TIMESTAMPDIFF'),'greeting based on user message history not client clock');
voiceBrainCheck(str_contains($brain,"idle_min")&&str_contains($brain,"CURRENT_DATE()"),'first conversation per day and idle period');
voiceBrainCheck(str_contains($brain,"gaw_append($pdo,$org,$uid,$thread,'user'")&&str_contains($brain,"gaw_append($pdo,$org,$uid,$thread,'agent'"),'KDS user and agent replies saved to existing Agent Brain');
voiceBrainCheck(str_contains($brain,"actorUserId"),'manager-mediated speaker logs retain actor identity');
voiceBrainCheck(str_contains($api,'avc_verified_speaker')&&str_contains($api,'avc_greeting'),'Global Agent only greets verified voice owner');
voiceBrainCheck(str_contains($global,'identifySpeaker')&&str_contains($global,'sessionUserMatch'),'global matching preserves signed-in account boundary');
voiceBrainCheck(str_contains($kds,'kda_spoken_personalization'),'KDS uses verified voice personalization');
voiceBrainCheck(str_contains($kds,'kso_ticket($current,$slot)'),'KDS slot readout uses canonical ticket with actual POS number');
voiceBrainCheck(str_contains($kds,'foreach($tickets as $index=>$row)'),'KDS read-all includes all active orders, not 8/20 max');
voiceBrainCheck(str_contains($page,'js/kds-spoken-orders.js?v=20261013-natural1'),'natural speech module loads on KDS page');
voiceBrainCheck(str_contains($sidebar,'id="kdsRecognizeSpeaker"'),'explicit identify speaker control exists');
voiceBrainCheck(str_contains($sidebar,"GelatoGlobalAgent?.identifySpeaker"),'reuse voice capture/match flow instead of separate recognition algorithm');
voiceBrainCheck(str_contains($voice,'voiceEventId:window.GelatoGlobalAgent?.verifiedSpeaker?.eventId'),'KDS event identifier only from verified identity');
voiceBrainCheck(str_contains($voice,"askKitchen('read order '"),'voice order queries use canonical permission-scoped server');
voiceBrainCheck(str_contains($history,"function gaw_history_page(")&&str_contains($history,'AND user_id=?'),'history scoped by user and organization');
voiceBrainCheck(str_contains($history,"nextBeforeId")&&str_contains($history,'created_at'),'full timestamped history paginates');
voiceBrainCheck(str_contains($history,"function gaw_history_threads(")&&str_contains($history,'archived_at'),'archived history accessible to owner');
voiceBrainCheck(str_contains($api,"history_page")&&str_contains($api,"history_threads"),'history endpoints available');
voiceBrainCheck(str_contains($canvas,'gda-history-toggle')&&str_contains($canvas,'gda-load-older'),'Agent canvas has history controls');
voiceBrainCheck(str_contains($canvas,'gda-time')&&str_contains($canvas,'m.created_at'),'message timestamps rendered');
voiceBrainCheck(!str_contains($brain,'CREATE TABLE'),'no new shadow memory tables or database migrations');
echo "agent-natural-voice-history-contract=ok\n";
